<script setup lang="ts">
import { lazyStrings } from '@/strings';
import { generateId } from '@/01-models/id';
import { idToRaw } from '@/01-models/ids';
import type { RecipeModelPatternEditorItemId } from '@/01-models/ids';
import { ref, computed, watch } from 'vue';
import {
  XIcon, ChefHatIcon, CopyIcon, CheckIcon, PlusIcon, Trash2Icon, InfoIcon, GlobeIcon, AlertCircleIcon, MessageSquareQuoteIcon,
} from 'lucide-vue-next';
import type { ChatGroupRecipe, RecipeSystemPrompt } from '@/features/recipes/logic/recipe';
import type { LmParameters, SystemPrompt } from '@/01-models/types';
import { generateDefaultModelPatterns } from '@/features/recipes/logic/recipe-matcher';

const props = defineProps<{
  isOpen: boolean,
  groupName: string,
  systemPrompt?: SystemPrompt,
  lmParameters?: LmParameters,
  initialModelId?: string,
}>();

const emit = defineEmits<{
  (e: 'close'): void,
}>();

type RecipeModelPatternEditorItem = {
  id: RecipeModelPatternEditorItemId,
  pattern: string,
  caseSensitive: boolean,
};

type RecipeExportForm = {
  name: string,
  description: string,
  systemPrompt: SystemPrompt,
  models: RecipeModelPatternEditorItem[],
};

const recipeForm = ref<RecipeExportForm>({
  name: props.groupName,
  description: '',
  systemPrompt: props.systemPrompt ? { ...props.systemPrompt } : { content: '', behavior: 'override' },
  models: [],
});

function initForm() {
  const modelPatterns = props.initialModelId
    ? generateDefaultModelPatterns({ modelId: props.initialModelId }).map(p => ({ id: generateId<RecipeModelPatternEditorItemId>(), pattern: p, caseSensitive: false }))
    : [];

  recipeForm.value = {
    name: props.groupName,
    description: '',
    systemPrompt: props.systemPrompt ? { ...props.systemPrompt } : { content: '', behavior: 'override' },
    models: modelPatterns,
  };
}

// Reset form when modal opens
watch(() => props.isOpen, (open) => {
  if (open) {
    initForm();
  }
});

const copySuccess = ref(false);

const exportedRecipeJson = computed(() => {
  // Use behavior 'override' with content null for "Clear"
  const hasSystemPrompt = recipeForm.value.systemPrompt.content !== null || recipeForm.value.systemPrompt.behavior === 'append';
  const isExplicitClear = recipeForm.value.systemPrompt.behavior === 'override' && recipeForm.value.systemPrompt.content === null;

  const recipe: ChatGroupRecipe = {
    type: 'chat_group_recipe',
    name: recipeForm.value.name,
    description: recipeForm.value.description || undefined,
    systemPrompt: (hasSystemPrompt || isExplicitClear) ? (recipeForm.value.systemPrompt as RecipeSystemPrompt) : undefined,
    lmParameters: props.lmParameters,
    models: recipeForm.value.models.map(m => ({
      type: 'regex',
      pattern: m.pattern,
      flags: m.caseSensitive ? [] : ['i'],
    })),
  };

  return JSON.stringify(recipe, null, 2);
});

function addModelPattern() {
  recipeForm.value.models.push({ id: generateId<RecipeModelPatternEditorItemId>(), pattern: '', caseSensitive: false });
}

function removeModelPattern({ id }: { id: RecipeModelPatternEditorItemId }) {
  const index = recipeForm.value.models.findIndex(m => m.id === id);
  if (index !== -1) {
    recipeForm.value.models.splice(index, 1);
  }
}

function isRegexValid({ pattern }: { pattern: string }): boolean {
  if (!pattern) return true;
  try {
    new RegExp(pattern);
    return true;
  } catch (e) {
    return false;
  }
}

async function copyToClipboard() {
  if (exportedRecipeJson.value) {
    await navigator.clipboard.writeText(exportedRecipeJson.value);
    copySuccess.value = true;
    setTimeout(() => {
      copySuccess.value = false;
    }, 2000);
  }
}


defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      // Export internal state and logic used only for testing here. Do not reference these in production logic.
    },
  }) || {}),
});

