            <div tw-class="grid grid-cols-1 gap-6">
              <div tw-class="space-y-2">
                <label tw-class="block text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">{{ lazyStrings.RecipeExportModal__recipe_name() }}</label>
                <input
